  (((double)adc_T)/131072.0 – ((double) dig_T1)/8192.0)) * ((double)dig_T3); 
 t_fine = (BME280_S32_t)(var1 + var2); 
 T  = (var1 + var2) / 5120.0; 
 return T; 
} 
// Returns pressure in Pa as double. Output value of “96386.2” equals 96386.2 Pa = 963.862 hPa 
